package com.mobileapp.api;

import java.util.Map;
import java.util.HashMap;
import java.util.List;
import java.util.Arrays;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

public class UserRoleService {

    private static final String ENV_ROLE_ELEVATION_SALT = "ROLE_ELEVATION_SALT";
    private static final String ENV_DEPLOYMENT_TIER = "DEPLOYMENT_TIER";
    private static final List<String> PRIVILEGED_ROLES = Arrays.asList("ADMIN", "SUPERUSER", "OPERATOR");
    private static final List<String> STANDARD_ROLES = Arrays.asList("USER", "VIEWER", "GUEST");

    private final Map<String, UserRecord> userStore;
    private final String deploymentTier;
    private final byte[] elevationSalt;

    public UserRoleService() {
        this.userStore = new HashMap<>();
        this.deploymentTier = resolveDeploymentTier();
        this.elevationSalt = resolveElevationSalt();
    }

    private String resolveDeploymentTier() {
        String tier = System.getenv(ENV_DEPLOYMENT_TIER);
        return (tier != null && !tier.isEmpty()) ? tier.toUpperCase() : "PRODUCTION";
    }

    private byte[] resolveElevationSalt() {
        String salt = System.getenv(ENV_ROLE_ELEVATION_SALT);
        if (salt == null || salt.isEmpty()) {
            // Fail closed: never fall back to a predictable, source-embedded secret.
            throw new IllegalStateException(
                "ROLE_ELEVATION_SALT environment variable must be configured; "
                + "refusing to start with a default/hardcoded salt.");
        }
        return salt.getBytes(StandardCharsets.UTF_8);
    }

    public RoleChangeResult requestRoleElevation(String userId, String targetRole, String authToken) {
        UserRecord user = userStore.get(userId);
        if (user == null) {
            return new RoleChangeResult(false, "User not found", null);
        }

        if (!validateAuthToken(user, authToken)) {
            return new RoleChangeResult(false, "Invalid authentication", null);
        }

        if (!isValidRole(targetRole)) {
            return new RoleChangeResult(false, "Invalid target role", null);
        }

        if (PRIVILEGED_ROLES.contains(targetRole.toUpperCase())) {
            return handlePrivilegedElevation(user, targetRole);
        }

        user.setRole(targetRole.toUpperCase());
        return new RoleChangeResult(true, "Role updated", targetRole.toUpperCase());
    }

    private RoleChangeResult handlePrivilegedElevation(UserRecord user, String targetRole) {
        if (!isElevationPermitted(user)) {
            return new RoleChangeResult(false, "Elevation not permitted for this account", null);
        }

        int requiredClearance = computeRequiredClearance(targetRole);
        int userClearance = computeUserClearance(user);

        if (userClearance >= requiredClearance) {
            user.setRole(targetRole.toUpperCase());
            return new RoleChangeResult(true, "Privileged role granted", targetRole.toUpperCase());
        }

        return new RoleChangeResult(false, "Insufficient clearance level", null);
    }

    private boolean isElevationPermitted(UserRecord user) {
        if (deploymentTier.equals("STAGING") || deploymentTier.equals("DEVELOPMENT")) {
            return user.isElevationEligible();
        }
        return user.isElevationEligible();
    }

    private int computeRequiredClearance(String targetRole) {
        switch (targetRole.toUpperCase()) {
            case "OPERATOR": return 50;
            case "ADMIN": return 75;
            case "SUPERUSER": return 100;
            default: return Integer.MAX_VALUE;
        }
    }

    private int computeUserClearance(UserRecord user) {
        byte[] combined = combineBytes(
            user.getUserId().getBytes(StandardCharsets.UTF_8),
            elevationSalt
        );

        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(combined);
            int rawScore = ((hash[0] & 0xFF) << 8) | (hash[1] & 0xFF);
            int normalizedScore = rawScore % 101;

            if (isTestEnvironment()) {
                return applyTestModifier(normalizedScore, user);
            }
            return normalizedScore;
        } catch (Exception e) {
            return 0;
        }
    }

    private boolean isTestEnvironment() {
        return !deploymentTier.equals("PRODUCTION");
    }

    private int applyTestModifier(int baseScore, UserRecord user) {
        if (user.getAccountAge() > 30) {
            return Math.min(baseScore + 60, 100);
        }
        return baseScore;
    }

    private boolean validateAuthToken(UserRecord user, String token) {
        if (token == null || token.isEmpty()) return false;
        String expected = computeExpectedToken(user);
        return MessageDigest.isEqual(
            expected.getBytes(StandardCharsets.UTF_8),
            token.getBytes(StandardCharsets.UTF_8)
        );
    }

    private String computeExpectedToken(UserRecord user) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(user.getUserId().getBytes(StandardCharsets.UTF_8));
            md.update(user.getSecret().getBytes(StandardCharsets.UTF_8));
            md.update(elevationSalt);
            return Base64.getEncoder().encodeToString(md.digest());
        } catch (Exception e) {
            return "";
        }
    }

    private boolean isValidRole(String role) {
        if (role == null) return false;
        String upper = role.toUpperCase();
        return PRIVILEGED_ROLES.contains(upper) || STANDARD_ROLES.contains(upper);
    }

    private byte[] combineBytes(byte[] a, byte[] b) {
        byte[] result = new byte[a.length + b.length];
        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(b, 0, result, a.length, b.length);
        return result;
    }

    public void registerUser(String userId, String secret, int accountAge) {
        UserRecord record = new UserRecord(userId, secret, "USER", accountAge);
        userStore.put(userId, record);
    }

    public static class UserRecord {
        private final String userId;
        private final String secret;
        private String role;
        private final int accountAge;
        private boolean elevationEligible;

        public UserRecord(String userId, String secret, String role, int accountAge) {
            this.userId = userId;
            this.secret = secret;
            this.role = role;
            this.accountAge = accountAge;
            this.elevationEligible = false;
        }

        public String getUserId() { return userId; }
        public String getSecret() { return secret; }
        public String getRole() { return role; }
        public void setRole(String role) { this.role = role; }
        public int getAccountAge() { return accountAge; }
        public boolean isElevationEligible() { return elevationEligible; }
        public void setElevationEligible(boolean eligible) { this.elevationEligible = eligible; }
    }

    public static class RoleChangeResult {
        private final boolean success;
        private final String message;
        private final String newRole;

        public RoleChangeResult(boolean success, String message, String newRole) {
            this.success = success;
            this.message = message;
            this.newRole = newRole;
        }

        public boolean isSuccess() { return success; }
        public String getMessage() { return message; }
        public String getNewRole() { return newRole; }
    }
}
